action.command:
cd /workspace && docker compose exec -T backend node -e '
(async () => {
  const r = await fetch("http://backend:4000/api/v1/swagger/swagger-ui-init.js");
  const txt = await r.txt();
  const start = txt.indexOf("\"swaggerDoc\"");
  const spec = JSON.parse(txt.slice(start + "\"swaggerDoc\"".length + 2, txt.lastIndexOf("}")) );
  const init = spec.paths["/auth/init-email-login"];
  console.log("INIT body:", JSON.stringify(init.post.requestBody.content["application/json"].schema));
  const ref = init.post.requestBody.content["application/json"].schema.$ref || Object.values(init.post.requestBody.content["application/json"].schema.allOf||[{}]).map(s=>s.$ref);
  console.log("refs:", ref);
})();
' 2>&1 | head -20

